const PHOTO="assets/illustration-80c334a2ae.webp",TEAM="assets/illustration-ed5c01ff3e.webp",HERO="assets/illustration-46ef4a9fbf.webp";
'use strict';
const PROGRAM={code:'65-51-H/01',years:[1,2,3],student:'DEMO-001',teacher:'PED-01',framework:'1.0',rubric:'1.0'};
const CODES=new Map(CS.competencies.map(c=>[c.code,c]));
const MODS=new Map(CS.modules.map(m=>[m.id,m]));
const EXTENSIONS={M21:['K04.3','K07.3']};
function availableAt(code,moduleId){
  return CODES.get(code)?.module===moduleId || !!EXTENSIONS[moduleId]?.includes(code);
}
const STORE='mistr-sveta.offline.v1', PREF='mistr-sveta.den.pref.v1';
const actors={student:PROGRAM.student,teacher:PROGRAM.teacher,leader:'VED-01'};
function cleanText(s,n=4000){return typeof s==='string' && s===s.trim() && s.length>0 && s.length<=n}
function valid(cond){if(!cond)throw new Error('invalid-record')}
function iid(){return crypto.randomUUID?.() || Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('')}
function emptyState(){return {events:[],assignments:{},evidence:{},assessments:{},confirmed:{}}}
function eventMeta(e,a){return {id:e.id,at:e.at,actor:e.actor,kind:e.kind,assignment:a.id,code:a.code,level:a.level,module:a.module,rubric:PROGRAM.rubric}}
function applyEvent(s,e){
  valid(e && typeof e==='object' && cleanText(e.id,100) && /^[A-Za-z0-9-]+$/.test(e.id) && !['constructor','prototype'].includes(e.id) && !s.events.some(x=>x.id===e.id));
  valid(typeof e.at==='string' && /^\d{4}-\d{2}-\d{2}T/.test(e.at) && Number.isFinite(Date.parse(e.at)));
  valid(e.framework===PROGRAM.framework && e.rubric===PROGRAM.rubric && ['cs','sk'].includes(e.lang));
  const teacher=e.actor===PROGRAM.teacher, pupil=e.actor===PROGRAM.student;
  const a=s.assignments[e.assignment];
  if(e.kind==='assign'){
    valid(teacher && e.assignment===e.id && !a && CODES.has(e.code) && [1,2,3].includes(e.level) && availableAt(e.code,e.module));
    valid(!Object.values(s.assignments).some(x=>x.code===e.code && x.level===e.level && x.module===e.module && ['assigned','working','submitted','returned'].includes(x.status)));
    s.assignments[e.id]={id:e.id,code:e.code,module:e.module,level:e.level,status:'assigned',proof:[],decisions:[]};
  }else{
    valid(a && e.code===a.code && e.level===a.level && e.module===a.module);
    if(e.kind==='start'){
      valid(pupil && ['assigned','returned','failed'].includes(a.status));
      valid(!Object.values(s.assignments).some(x=>x.id!==a.id && x.code===a.code && x.level===a.level && x.module===a.module && ['assigned','working','submitted','returned'].includes(x.status)));
      a.status='working';
    }else if(e.kind==='submit'){
      valid(pupil && a.status==='working' && cleanText(e.text));
      if(e.sourceEvidence){const shared=s.evidence[e.sourceEvidence];valid(shared && shared.code!==a.code && shared.text===e.text && (a.code.startsWith('K12.')||shared.code.startsWith('K12.')||CODES.get(shared.code).module===CODES.get(a.code).module))}
      s.evidence[e.id]={...eventMeta(e,a),text:e.text,lang:e.lang,...(e.sourceEvidence?{sourceEvidence:e.sourceEvidence}:{})};a.proof.push(e.id);a.status='submitted';
    }else if(e.kind==='review'){
      valid(teacher && a.status==='submitted' && e.proof===a.proof.at(-1) && ['approved','returned','failed'].includes(e.result));
      valid(Array.isArray(e.checks) && e.checks.length===3 && e.checks.every(x=>['yes','no','unknown'].includes(x)));
      valid(['safe','critical','unknown'].includes(e.safety) && typeof e.note==='string' && e.note.length<=3000);
      valid(e.safety!=='critical' || e.result==='failed');
      valid(e.result!=='approved' || (e.safety==='safe' && e.checks.every(x=>x==='yes')));
      valid(e.result==='approved' || cleanText(e.note,3000));
      s.assessments[e.id]={...eventMeta(e,a),proof:e.proof,checks:[...e.checks],safety:e.safety,result:e.result,note:e.note,lang:e.lang};
      a.decisions.push(e.id);a.status=e.result;
      if(e.result==='approved')s.confirmed[a.code]=Math.max(s.confirmed[a.code]||0,a.level);
    }else{throw new Error('unknown-event')}
  }
  s.events.push(e);return s;
}
function replay(events){
  valid(Array.isArray(events) && events.length<=6000);
  return events.reduce(applyEvent,emptyState());
}
function demoEvents(){
  const time=new Date('2026-11-13T08:00:00.000Z');
  return ['K01.1','K03.1'].map((code,i)=>{let id='demo-assignment-'+(i+1);return {kind:'assign',actor:PROGRAM.teacher,id,assignment:id,code,level:1,module:CODES.get(code).module,framework:PROGRAM.framework,rubric:PROGRAM.rubric,at:new Date(time.getTime()+i*60000).toISOString(),lang:'cs'}});
}
function readStore(){
  const raw=localStorage.getItem(STORE);
  if(!raw)return {events:demoEvents(),drafts:{},revision:null};
  const d=JSON.parse(raw);valid(d.v===1 && typeof d.drafts==='object' && d.drafts!==null);
  replay(d.events);return d;
}
function makeEvent(kind,role,lang,target,extra={}){
  const id=iid();
  const actor=actors[role];valid(!!actor && role===(['assign','review'].includes(kind)?'teacher':'student'));
  return {kind,actor,id,assignment:kind==='assign'?id:target.id,code:target.code,module:target.module,level:target.level,lang,framework:PROGRAM.framework,rubric:PROGRAM.rubric,at:new Date().toISOString(),...extra};
}
function exportBundle(state,lang){
  const data=lang==='sk'?SK:CS,comp=id=>data.competencies.find(c=>c.code===id);
  return {format:'mistr-sveta-demo',version:1,exportedAt:new Date().toISOString(),language:lang,student:PROGRAM.student,program:PROGRAM.code,framework:PROGRAM.framework,rubric:PROGRAM.rubric,mappingStatus:'draft',
    confirmed:Object.entries(state.confirmed).map(([code,level])=>({code,level,name:comp(code).name,approvals:Object.values(state.assessments).filter(r=>r.code===code&&r.result==='approved').map(r=>r.id)})),
    evidence:Object.values(state.evidence),assessments:Object.values(state.assessments).map(r=>({...r,standard:comp(r.code).levels[r.level-1],criteria:comp(r.code).checks.map((label,i)=>({id:r.code+'-C'+(i+1),label,decision:r.checks[i]}))})),
    events:state.events};
}
function parseBundle(b){
  valid(b && b.format==='mistr-sveta-demo' && b.version===1 && b.framework===PROGRAM.framework && b.rubric===PROGRAM.rubric && b.student===PROGRAM.student && b.program===PROGRAM.code && b.mappingStatus==='draft' && ['cs','sk'].includes(b.language));
  const rebuilt=replay(b.events),actual=exportBundle(rebuilt,b.language);
  for(const k of ['confirmed','evidence','assessments'])valid(JSON.stringify(b[k])===JSON.stringify(actual[k]));
  return rebuilt;
}
function mergeBundle(existing,incoming){
  const all=existing.events.slice(), byId=new Map(all.map(x=>[x.id,x]));
  for(const e of incoming.events){
    const old=byId.get(e.id);
    if(old){valid(JSON.stringify(old)===JSON.stringify(e));continue}
    byId.set(e.id,e);all.push(e);
  }
  return replay(all);
}

